import { mkdtemp, mkdir, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'

// Task folders generated by the security specs at run time (docs/testing.md §8.6). They live in temporary directories
// so the shared fixture tasks stay untouched; remove them with `removeTaskDir`.

/**
 * `secret-paths`: a Python task with a writeOnly field in every config and in the result. The schedule derives each
 * analysis key from the scan's secret seed, and the result reports SHA-256 hashes of what the task received, so tests
 * can prove that the task saw the plaintext while every response shows `***`. `fallback` is a nullable secret with a
 * default of its own: omitted, the task must see that default (docs/tasks.md §6.5).
 */
export const SECRET_PATHS_FALLBACK = 'built-in-fallback'

export const SECRET_PATHS_TASK: Record<string, string> = {
  'scantor.yaml': 'scantor: 1\nname: secret-paths\nlanguage: python\ndescription: "Security fixture: writeOnly fields in every config and in the result."\n',
  Dockerfile: 'ARG SCANTOR_BASE\nFROM ${SCANTOR_BASE}\nCOPY . .\n',
  '.dockerignore': '.git\n__pycache__\n.scantor\n',
  'main.py': `"""secret-paths: writeOnly fields in the task, scan and analysis configs and in the result."""

import hashlib
from collections.abc import Iterator

from pydantic import BaseModel, Field, SecretStr

import scantor


class TaskConfig(scantor.Config):
    token: SecretStr | None = Field(default=None, description="A writeOnly task config value.")
    fallback: SecretStr | None = Field(default=SecretStr("${SECRET_PATHS_FALLBACK}"), description="A writeOnly value with a default.")


class ScanConfig(scantor.Config):
    count: int = Field(default=2, ge=1, le=10)
    seed: SecretStr = Field(description="A writeOnly scan config value.")


class AnalysisConfig(scantor.Config):
    n: int
    key: SecretStr


class Result(BaseModel):
    n: int
    echo: SecretStr
    token_sha256: str | None
    key_sha256: str
    fallback_sha256: str | None


def sha256(value: SecretStr | None) -> str | None:
    return hashlib.sha256(value.get_secret_value().encode()).hexdigest() if value is not None else None


def schedule(ctx: scantor.Context, scan_config: ScanConfig, task_config: TaskConfig) -> Iterator[AnalysisConfig]:
    for n in range(scan_config.count):
        yield AnalysisConfig(n=n, key=SecretStr(f"key-{scan_config.seed.get_secret_value()}-{n}"))


def run(ctx: scantor.Context, analysis_config: AnalysisConfig, task_config: TaskConfig) -> Result:
    return Result(
        n=analysis_config.n,
        echo=analysis_config.key,
        token_sha256=sha256(task_config.token),
        key_sha256=sha256(analysis_config.key) or "",
        fallback_sha256=sha256(task_config.fallback),
    )


task = scantor.Task(
    task_config=TaskConfig,
    scan_config=ScanConfig,
    analysis_config=AnalysisConfig,
    result=Result,
    schedule=schedule,
    run=run,
)
`,
}

/**
 * `metadata-build`: a task whose Dockerfile connects to the cloud metadata address during the build and prints the
 * error it gets, so a test can tell a rejected connection (egress deny list) from a timeout.
 */
export const METADATA_BUILD_TASK: Record<string, string> = {
  'scantor.yaml': 'scantor: 1\nname: metadata-build\nlanguage: python\ndescription: "Security fixture: a RUN step that connects to 169.254.169.254."\n',
  Dockerfile: ['ARG SCANTOR_BASE', 'FROM ${SCANTOR_BASE}', 'COPY . .', 'RUN ["python", "probe_metadata.py"]', ''].join('\n'),
  '.dockerignore': '.git\n__pycache__\n.scantor\n',
  'probe_metadata.py': `import socket
import sys

try:
    socket.create_connection(("169.254.169.254", 80), timeout=10).close()
except OSError as exc:
    print(f"metadata probe failed: {type(exc).__name__}: errno={exc.errno} {exc}", flush=True)
    sys.exit(1)
print("metadata probe connected", flush=True)
`,
  'main.py': `from pydantic import BaseModel

import scantor


class Result(BaseModel):
    ok: bool


def run(ctx: scantor.Context, analysis_config: scantor.Empty, task_config: scantor.Empty) -> Result:
    return Result(ok=True)


task = scantor.Task(result=Result, run=run)
`,
}

/** The files of the `probe` task's mode `files`: name → declared content type (the download headers depend only on it). */
export const FILE_TYPES: Record<string, string> = {
  'x.jpg': 'image/jpeg',
  'x.gif': 'image/gif',
  'x.webp': 'image/webp',
  'x.json': 'application/json',
  'x.pdf': 'application/pdf',
  'x.txt': 'text/plain',
  'x.js': 'text/javascript',
}

/** The lines the `probe` task's mode `hang` writes to stdout, stderr and its log before it waits. */
export const PROBE_MARKERS = { stdout: 'probe stdout marker', stderr: 'probe stderr marker', log: 'probe log marker' }

/**
 * `probe`: the security specs' general-purpose task, published once per worker (every publish costs a build slot).
 * Mode `ok` returns at once; `files` returns a file per FILE_TYPES entry with that content type; `hang` writes the
 * PROBE_MARKERS and then waits past its analysis timeout, so its worker stays up for container and log checks. It
 * never prints its config (`label`, the writeOnly `token`).
 */
export const PROBE_TASK: Record<string, string> = {
  'scantor.yaml': 'scantor: 1\nname: probe\nlanguage: python\ndescription: "Security fixture: returns, writes files or hangs."\n',
  Dockerfile: 'ARG SCANTOR_BASE\nFROM ${SCANTOR_BASE}\nCOPY . .\n',
  '.dockerignore': '.git\n__pycache__\n.scantor\n',
  'main.py': `"""probe: returns, writes files of several content types, or prints markers and hangs; never prints its config."""

import sys
import time
from typing import Literal

from pydantic import BaseModel, SecretStr

import scantor

FILES = ${JSON.stringify(FILE_TYPES)}
MARKERS = ${JSON.stringify(PROBE_MARKERS)}


class TaskConfig(scantor.Config):
    mode: Literal["ok", "files", "hang"] = "ok"
    label: str = "probe"
    token: SecretStr | None = None


class Result(BaseModel):
    mode: str
    files: list[scantor.FileRef]


def run(ctx: scantor.Context, analysis_config: scantor.Empty, task_config: TaskConfig) -> Result:
    files: list[scantor.FileRef] = []
    if task_config.mode == "files":
        files = [ctx.files.put(name, f"content of {name}", content_type) for name, content_type in FILES.items()]
    elif task_config.mode == "hang":
        print(MARKERS["stdout"], flush=True)
        print(MARKERS["stderr"], file=sys.stderr, flush=True)
        ctx.log("info", MARKERS["log"])
        time.sleep((ctx.remaining() or 600) + 60)
    return Result(mode=task_config.mode, files=files)


task = scantor.Task(task_config=TaskConfig, result=Result, run=run)
`,
}

/** Writes a task folder (path → content) into a new temporary directory and returns it. */
export async function writeTaskDir(files: Record<string, string>, prefix = 'security-task'): Promise<string> {
  const dir = await mkdtemp(join(tmpdir(), `${prefix}-`))
  for (const [path, content] of Object.entries(files)) {
    await mkdir(dirname(join(dir, path)), { recursive: true })
    await writeFile(join(dir, path), content)
  }
  return dir
}

export async function removeTaskDir(dir: string): Promise<void> {
  await rm(dir, { recursive: true, force: true })
}
